"""The checkout a Copilot v2 run works in, as the runtime sees it.

The runtime only needs to know which branch it is on, where the files are, and
how to move to a new branch. How branches are created and checked out is the
host's business, so the host implements this protocol and the runtime never
imports it.
"""

from __future__ import annotations

from pathlib import Path
from typing import TYPE_CHECKING, Protocol

if TYPE_CHECKING:
    from rasa.builder.project_generator import ProjectGenerator


class BranchOffError(Exception):
    """Raised by ``CopilotWorkspace.branch_off`` when no branch could be created.

    The message is shown to the model, so it says what to do differently.
    """


class CopilotWorkspace(Protocol):
    """One agent's current branch checkout, which can move to a new branch."""

    @property
    def branch(self) -> str:
        """Name of the branch currently checked out."""
        ...

    @property
    def path(self) -> Path:
        """Folder of the current branch's checkout."""
        ...

    @property
    def project_generator(self) -> "ProjectGenerator":
        """The generator operating on the current branch's checkout."""
        ...

    async def branch_off(self, name: str) -> str:
        """Create a branch from the current one and switch to it.

        The name is made unique if it is taken.

        Args:
            name: Wanted name of the new branch.

        Returns:
            The name of the branch created, which is now the current one.

        Raises:
            BranchOffError: If no branch could be created.
        """
        ...
